/**
 * Minimal hash-based SPA router that works entirely on window.location.hash.
 * No History API usage — only hash reads/writes and 'hashchange' events.
 */

/**
 * Compile a route pattern like "#/users/:id" into a RegExp plus ordered
 * param names. Accepts patterns with or without a leading "#".
 */
function compilePattern(pattern) {
  let p = String(pattern);
  if (p.startsWith('#')) p = p.slice(1);
  if (!p.startsWith('/')) p = '/' + p;
  const paramNames = [];
  const regexSource = p
    .split('/')
    .map((segment) => {
      if (segment.startsWith(':')) {
        paramNames.push(segment.slice(1));
        return '([^/]+)';
      }
      return segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    })
    .join('/');
  return { regex: new RegExp(`^${regexSource}/?$`), paramNames };
}

/** Parse "/path?a=1&b=2" into { pathname, query } where query values are decoded. */
function parseHash(hash) {
  let h = hash || '';
  if (h.startsWith('#')) h = h.slice(1);
  if (!h.startsWith('/')) h = '/' + h;
  const qIndex = h.indexOf('?');
  let pathname = h;
  const query = {};
  if (qIndex !== -1) {
    pathname = h.slice(0, qIndex);
    const qs = h.slice(qIndex + 1);
    for (const pair of qs.split('&')) {
      if (!pair) continue;
      const eq = pair.indexOf('=');
      const key = eq === -1 ? pair : pair.slice(0, eq);
      const value = eq === -1 ? '' : pair.slice(eq + 1);
      query[decodeURIComponent(key)] = decodeURIComponent(value);
    }
  }
  return { pathname, query };
}

/**
 * Create the router.
 *
 * @param {Object<string, Function>} routes map of "#/users/:id" -> handler(ctx)
 * @param {{ onChange?: Function }} [options] onChange({ path, name }) fires after every render
 * @returns {{
 *   current: () => {pathname: string, params: Object, query: Object},
 *   navigate: (path: string, replace?: boolean) => void,
 *   destroy: () => void,
 *   handleClick: (event: MouseEvent) => boolean,
 *   installLinkInterceptor: (root?: Document|Element) => void,
 * }}
 */
export function createRouter(routes, { onChange } = {}) {
  const compiled = Object.entries(routes).map(([pattern, handler]) => ({
    pattern,
    handler,
    ...compilePattern(pattern),
  }));

  function resolve(pathname) {
    for (const route of compiled) {
      const match = route.regex.exec(pathname);
      if (!match) continue;
      const params = {};
      route.paramNames.forEach((name, i) => {
        params[name] = decodeURIComponent(match[i + 1]);
      });
      return { route, params };
    }
    return null;
  }

  function render() {
    const { pathname, query } = parseHash(window.location.hash);
    const found = resolve(pathname);
    if (found) {
      found.route.handler({ params: found.params, query, path: pathname });
      if (onChange) onChange({ path: pathname, matched: true });
    } else {
      routes.notFound({ params: {}, query, path: pathname });
      if (onChange) onChange({ path: pathname, matched: false });
    }
  }

  /**
   * Programmatic navigation: sets location.hash; the resulting hashchange
   * event triggers rendering. Falls back to a direct render when the hash
   * is unchanged (no event will fire).
   */
  function navigate(path, replace = false) {
    const target = path.startsWith('#') ? path : '#' + path;
    const prev = window.location.hash;
    if (replace) {
      // jsdom supports replaceState-free hash replacement via this trick:
      // setting hash always pushes in some browsers, so emulate replace.
      const url = new URL(window.location.href);
      url.hash = target;
      window.history.replaceState(null, '', url.href); // allowed: not pushState
    } else {
      window.location.hash = target;
    }
    if (window.location.hash === prev && target !== prev) {
      render();
    } else if (window.location.hash === prev) {
      render(); // same-path navigation should still invoke the handler
    }
  }

  /**
   * Anchor-click interceptor. Returns true when the router took over the click.
   * Preserves default browser behavior for modified clicks:
   *   - ctrlKey / metaKey ("open in new tab")
   *   - shiftKey / altKey
   *   - button !== 0 (middle/right click)
   *   - anchors with target="_blank"
   */
  function handleClick(event) {
    const anchor =
      event.target instanceof Element ? event.target.closest('a[href]') : null;
    if (!anchor) return false;

    const href = anchor.getAttribute('href') || '';
    if (!(href.startsWith('#/') || href.startsWith('#?'))) return false;
    if (anchor.target === '_blank') return false;
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.ctrlKey ||
      event.metaKey ||
      event.shiftKey ||
      event.altKey
    ) {
      return false; // let the browser handle it
    }

    event.preventDefault();
    navigate(href);
    return true;
  }

  /** Install a delegated listener so dynamically-added links work too. */
  function installLinkInterceptor(root = document) {
    root.addEventListener('click', handleClick);
  }

  window.addEventListener('hashchange', render);

  // Render the current location once on startup.
  if (typeof window.location.hash === 'string' && window.location.hash) {
    render();
  }

  return {
    current() {
      const { pathname, query } = parseHash(window.location.hash);
      const found = resolve(pathname);
      return {
        pathname,
        query,
        params: found ? found.params : null,
        matched: Boolean(found),
      };
    },
    navigate,
    destroy() {
      window.removeEventListener('hashchange', render);
    },
    handleClick,
    installLinkInterceptor,
    render,
  };
}

export default createRouter;

