import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { createRouter } from '../src/router.js';

function setHash(hash) {
  window.location.hash = hash;
}

/** Fire a real HashChangeEvent like a user/anchor navigation would. */
function dispatchHashChange(oldURL, newURL) {
  window.dispatchEvent(
    new HashChangeEvent('hashchange', {
      oldURL,
      newURL,
      bubbles: false,
      cancelable: false,
    })
  );
}

function clickOn(anchor, init = {}) {
  const event = new MouseEvent('click', {
    bubbles: true,
    cancelable: true,
    button: 0,
    view: window,
    ...init,
  });
  anchor.dispatchEvent(event);
  return event;
}

beforeEach(() => {
  document.body.innerHTML = '';
  setHash('#/');
});

describe('createRouter', () => {
  let cleanup = [];
  afterEach(() => {
    cleanup.forEach((fn) => fn());
    cleanup = [];
  });

  function track(router) {
    cleanup.push(() => router.destroy());
    return router;
  }

  it('dispatches hashchange-driven handler calls with params', () => {
    const usersHandler = vi.fn();
    const router = track(createRouter({ '#/users/:id': usersHandler }));

    setHash('#/users/42');
    dispatchHashChange('http://localhost/#/users/41', 'http://localhost/#/users/42');

    expect(usersHandler).toHaveBeenCalledTimes(1);
    expect(usersHandler).toHaveBeenCalledWith(
      expect.objectContaining({ params: { id: '42' } })
    );
    expect(router.current().matched).toBe(true);
  });

  it('matches multiple params and decodes them', () => {
    const handler = vi.fn();
    track(createRouter({ '#/users/:id/posts/:postId': handler }));

    setHash('#/users/7/posts/hello%20world');
    dispatchHashChange('', 'http://localhost/#/users/7/posts/hello%20world');

    expect(handler).toHaveBeenCalledWith(
      expect.objectContaining({ params: { id: '7', postId: 'hello world' } })
    );
  });

  it('parses query string after ? in the hash', () => {
    const handler = vi.fn();
    track(createRouter({ '#/search': handler }));

    setHash('#/search?q=hash%20routers&limit=10');
    dispatchHashChange('', 'http://localhost/#/search?q=hash%20routers&limit=10');

    expect(handler).toHaveBeenCalledWith(
      expect.objectContaining({
        params: {},
        query: { q: 'hash routers', limit: '10' },
      })
    );
  });

  it('supports query strings on parameterized routes', () => {
    const handler = vi.fn();
    track(createRouter({ '#/items/:id': handler }));

    setHash('#/items/3?tab=details&flag');
    dispatchHashChange('', 'http://localhost/#/items/3?tab=details&flag');

    expect(handler).toHaveBeenCalledWith(
      expect.objectContaining({
        params: { id: '3' },
        query: { tab: 'details', flag: '' },
      })
    );
  });

  it('routes to notFound for unmatched paths', () => {
    const home = vi.fn();
    const notFound = vi.fn();
    track(createRouter({ '#/': home, notFound }));

    setHash('#/nowhere/at/all');
    dispatchHashChange('', 'http://localhost/#/nowhere/at/all');

    expect(home).not.toHaveBeenCalled();
    expect(notFound).toHaveBeenCalledTimes(1);
    expect(notFound).toHaveBeenCalledWith(
      expect.objectContaining({ path: '/nowhere/at/all', query: {} })
    );
  });

  it('navigate() sets the hash and the round trip invokes the handler', () => {
    const handler = vi.fn();
    const router = track(createRouter({ '#/about/team': handler }));

    router.navigate('/about/team');
    expect(window.location.hash).toBe('#/about/team');
    expect(handler).toHaveBeenCalledWith(
      expect.objectContaining({ params: {}, query: {}, path: '/about/team' })
    );

    // Round trip back out and in again.
    router.navigate('/');
    expect(handler).toHaveBeenCalledTimes(1);
    router.navigate('/about/team');
    expect(handler).toHaveBeenCalledTimes(2);

    // navigate accepts a leading # too.
    router.navigate('#/about/team');
    expect(handler).toHaveBeenCalledTimes(3);
  });

  it('navigate() with query string reaches handlers as parsed query', () => {
    const handler = vi.fn();
    const router = track(createRouter({ '#/products/:id': handler }));
    router.navigate('/products/9?color=red');
    expect(window.location.hash).toBe('#/products/9?color=red');
    expect(handler).toHaveBeenCalledWith(
      expect.objectContaining({ params: { id: '9' }, query: { color: 'red' } })
    );
  });

  it('fires onChange after every render with match info', () => {
    const onChange = vi.fn();
    track(createRouter({ '#/ok': vi.fn(), notFound: vi.fn() }, { onChange }));

    setHash('#/ok');
    dispatchHashChange('', '');
    setHash('#/nope');
    dispatchHashChange('', '');

    expect(onChange).toHaveBeenNthCalledWith(1, { path: '/ok', matched: true });
    expect(onChange).toHaveBeenNthCalledWith(2, { path: '/nope', matched: false });
  });

  describe('link-click interceptor', () => {
    function setupAnchor(href) {
      const anchor = document.createElement('a');
      anchor.setAttribute('href', href);
      document.body.appendChild(anchor);
      return anchor;
    }

    it('upgrades plain clicks on hash-slash anchors into router navigation', () => {
      const handler = vi.fn();
      const router = track(createRouter({ '#/docs/:page': handler }));
      router.installLinkInterceptor();

      const anchor = setupAnchor('#/docs/intro?ref=banner');
      const event = clickOn(anchor);

      expect(event.defaultPrevented).toBe(true);
      expect(window.location.hash).toBe('#/docs/intro?ref=banner');
      expect(handler).toHaveBeenCalledWith(
        expect.objectContaining({
          params: { page: 'intro' },
          query: { ref: 'banner' },
        })
      );
    });

    it('preserves default behavior for ctrl+click and meta+click', () => {
      const handler = vi.fn();
      const router = track(createRouter({ '#/newtab': handler }));
      router.installLinkInterceptor();

      for (const modifier of [{ ctrlKey: true }, { metaKey: true }]) {
        const anchor = setupAnchor('#/newtab');
        const event = clickOn(anchor, modifier);

        expect(event.defaultPrevented).toBe(false);
        expect(window.location.hash).not.toBe('#/newtab');
        expect(handler).not.toHaveBeenCalled();
        anchor.remove();
      }
    });

    it('ignores non-hash-slash anchors and non-left clicks', () => {
      const handler = vi.fn();
      const router = track(createRouter({ '#/x': handler }));
      router.installLinkInterceptor();

      // Plain http link — untouched.
      const external = setupAnchor('https://example.com/page');
      let event = clickOn(external);
      expect(event.defaultPrevented).toBe(false);
      expect(handler).not.toHaveBeenCalled();

      // Middle click on a hash link — untouched.
      const hashLink = setupAnchor('#/x');
      event = clickOn(hashLink, { button: 1 });
      expect(event.defaultPrevented).toBe(false);
      expect(handler).not.toHaveBeenCalled();

      // handleClick reports what it did.
      expect(router.handleClick(new MouseEvent('click'))).toBe(false);
      const good = setupAnchor('#/x');
      expect(router.handleClick(clickOn(good))).toBe(true);
      expect(handler).toHaveBeenCalledTimes(1);
    });

    it('works with clicks on children via delegation (closest)', () => {
      const handler = vi.fn();
      const router = track(createRouter({ '#/deep': handler }), {});
      router.installLinkInterceptor();

      const anchor = setupAnchor('#/deep');
      anchor.innerHTML = '<span>go</span>';
      clickOn(anchor.querySelector('span'));
      expect(handler).toHaveBeenCalledTimes(1);
    });
  });
});

